style.css:
/* =========================================
   COOL DARK NEON THEME FOR STYLUS/STYLISH
   Works on most websites
========================================= */

:root{
    --bg: #0d1117;
    --bg2: #161b22;
    --card: #1f2630;
    --text: #e6edf3;
    --accent: #00ffd5;
    --accent2: #7a5cff;
    --border: #30363d;
}

/* Smooth animations */
*{
    transition: all 0.25s ease;
    scrollbar-width: thin;
}

/* Main page */
body{
    background: linear-gradient(
        135deg,
        #0d1117,
        #111827,
        #161b22
    ) !important;

    color: var(--text) !important;
    font-family: "Segoe UI", sans-serif !important;
}

/* Cards / panels */
div,
section,
article,
main,
aside,
header,
footer,
nav{
    background-color: rgba(22,27,34,0.88) !important;
    border-radius: 16px !important;
    border: 1px solid var(--border) !important;
    backdrop-filter: blur(10px);
}

/* Neon glow hover */
div:hover,
section:hover,
article:hover{
    box-shadow:
        0 0 10px rgba(0,255,213,0.25),
        0 0 20px rgba(122,92,255,0.18) !important;

    transform: translateY(-2px);
}

/* Text */
p,
span,
li,
td,
label{
    color: var(--text) !important;
}

/* Headings */
h1,h2,h3,h4,h5{
    color: var(--accent) !important;
    text-shadow: 0 0 8px rgba(0,255,213,0.4);
}

/* Links */
a{
    color: #58a6ff !important;
    text-decoration: none !important;
}

a:hover{
    color: var(--accent) !important;
    text-shadow: 0 0 10px var(--accent);
}

/* Buttons */
button,
input[type="submit"]{
    background: linear-gradient(
        135deg,
        var(--accent2),
        var(--accent)
    ) !important;

    color: white !important;
    border: none !important;
    border-radius: 12px !important;
    padding: 10px 18px !important;
    font-weight: bold !important;

    box-shadow:
        0 0 12px rgba(0,255,213,0.25);
}

button:hover,
input[type="submit"]:hover{
    transform: scale(1.05);
    box-shadow:
        0 0 18px rgba(0,255,213,0.45);
}

/* Input fields */
input,
textarea,
select{
    background: #0f1720 !important;
    color: white !important;
    border: 1px solid var(--border) !important;
    border-radius: 10px !important;
}

/* Tables */
table{
    border-radius: 14px !important;
    overflow: hidden !important;
}

th{
    background: #21262d !important;
    color: var(--accent) !important;
}

td{
    background: #161b22 !important;
}

/* Scrollbar */
::-webkit-scrollbar{
    width: 10px;
}

::-webkit-scrollbar-track{
    background: #111827;
}

::-webkit-scrollbar-thumb{
    background: linear-gradient(
        var(--accent2),
        var(--accent)
    );
    border-radius: 20px;
}

/* Selection color */
::selection{
    background: var(--accent2);
    color: white;
}
